describe('Login Form Validation', () => {
    beforeEach(() => {
        cy.visit('/login');
    });

    it('should not allow submission with empty fields', () => {
        cy.get('form').submit();
        cy.get('.error-message').should('contain', 'Please fill out this field');
    });

    it('should show error messages for both fields when submitted empty', () => {
        cy.get('input[name="username"]').should('be.empty');
        cy.get('input[name="password"]').should('be.empty');
        cy.get('form').submit();
        cy.get('input[name="username"] + .error-message').should('contain', 'Please fill out this field');
        cy.get('input[name="password"] + .error-message').should('contain', 'Please fill out this field');
    });
});
